begin;
create extension if not exists pgcrypto;
create table if not exists inventory_warehouses(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,code text not null,name text not null,status text not null default 'active' check(status in ('active','inactive')),address text,manager_user_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists inventory_categories(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,code text not null,name text not null,parent_id uuid references inventory_categories(id),created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists inventory_units(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,code text not null,name text not null,factor numeric(20,6) not null default 1 check(factor>0),created_at timestamptz not null default now(),unique(tenant_id,code));
create table if not exists inventory_products(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,sku text not null,name text not null,category_id uuid references inventory_categories(id),unit_id uuid references inventory_units(id),barcode text,min_stock numeric(20,4) not null default 0,max_stock numeric(20,4) not null default 0,reorder_point numeric(20,4) not null default 0,status text not null default 'active' check(status in ('active','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,sku));
create table if not exists inventory_documents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,document_no text not null,type text not null check(type in ('receipt','issue','transfer','adjustment')),status text not null default 'draft' check(status in ('draft','posted','cancelled')),source_warehouse_id uuid references inventory_warehouses(id),target_warehouse_id uuid references inventory_warehouses(id),reason text,reference_no text,created_by uuid,posted_by uuid,created_at timestamptz not null default now(),posted_at timestamptz,unique(tenant_id,document_no));
create table if not exists inventory_document_items(id uuid primary key default gen_random_uuid(),document_id uuid not null references inventory_documents(id) on delete cascade,product_id uuid not null references inventory_products(id),quantity numeric(20,4) not null check(quantity>0),unit_price numeric(20,2) not null default 0);
create table if not exists inventory_stock(tenant_id uuid not null,warehouse_id uuid not null references inventory_warehouses(id) on delete cascade,product_id uuid not null references inventory_products(id) on delete cascade,quantity numeric(20,4) not null default 0,reserved_quantity numeric(20,4) not null default 0,updated_at timestamptz not null default now(),primary key(tenant_id,warehouse_id,product_id));
create table if not exists inventory_counts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,count_no text not null,warehouse_id uuid not null references inventory_warehouses(id),status text not null default 'draft' check(status in ('draft','counting','approved','cancelled')),count_date date not null default current_date,notes text,created_by uuid,approved_by uuid,created_at timestamptz not null default now(),unique(tenant_id,count_no));
create table if not exists inventory_count_items(id uuid primary key default gen_random_uuid(),count_id uuid not null references inventory_counts(id) on delete cascade,product_id uuid not null references inventory_products(id),system_quantity numeric(20,4) not null default 0,counted_quantity numeric(20,4),variance numeric(20,4));
create table if not exists inventory_events(id bigserial primary key,tenant_id uuid not null,entity_type text not null,entity_id uuid not null,event_type text not null,from_status text,to_status text,quantity numeric(20,4) default 0,actor_user_id uuid,reason text,created_at timestamptz not null default now());
create index if not exists inventory_events_idx on inventory_events(tenant_id,entity_type,entity_id,created_at desc);
insert into platform_modules(code,title,is_active) values('23-inventory-warehouse','انبار',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values('read','مشاهده انبار','modules:23-inventory-warehouse:read'),('write','ثبت و ویرایش انبار','modules:23-inventory-warehouse:write'),('post','قطعی‌سازی سند انبار','modules:23-inventory-warehouse:post'),('count','انبارگردانی','modules:23-inventory-warehouse:count'),('transfer','انتقال بین انبارها','modules:23-inventory-warehouse:transfer'))v(a,t,p) where m.code='23-inventory-warehouse' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;
commit;